<?php
namespace App\Models;use Astrotomic\Translatable\Contracts\Translatable as Contract;use Astrotomic\Translatable\Translatable;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\SoftDeletes;
class GalleryAlbum extends Model implements Contract{use Translatable,SoftDeletes;public array $translatedAttributes=['title','description'];protected $fillable=['gallery_category_id','tour_id','destination_id','tour_date','cover_image','is_active','sort_order'];protected $casts=['tour_date'=>'date','is_active'=>'boolean'];public function category(){return $this->belongsTo(GalleryCategory::class,'gallery_category_id');}public function tour(){return $this->belongsTo(Tour::class);}public function destination(){return $this->belongsTo(Destination::class);}public function media(){return $this->hasMany(GalleryMedia::class)->orderBy('sort_order');}}
